def scaled_dot_product_attention_oracle(query, key, value, attn_mask=None, dropout_p=0.,
                                        is_causal=False, *, scale=None, enable_gqa=False):
    """Raw NumPy SDPA with its own analytical VJP, independent of learner ops."""
    if dropout_p or enable_gqa or (is_causal and attn_mask is not None):
        raise _errors.BrowserUnsupported('Dropout, grouped-query or combined causal/masked SDPA requires the server')
    q, k, v = query._data, key._data, value._data
    if q.ndim < 2 or k.ndim < 2 or v.ndim < 2 or q.shape[-1] != k.shape[-1] or k.shape[-2] != v.shape[-2]:
        raise RuntimeError('Invalid SDPA shapes')
    if q.dtype != k.dtype or q.dtype != v.dtype or q.dtype.kind != 'f':
        raise RuntimeError('SDPA expects floating tensors with matching dtypes')
    # A NumPy float64 scalar promotes float32 arrays under NumPy 2.x. A Python
    # scalar keeps the input dtype, matching native attention's output contract.
    factor = float(1 / np.sqrt(q.shape[-1])) if scale is None else float(scale)
    scores = (q @ np.swapaxes(k, -1, -2)) * factor
    if is_causal:
        scores = np.where(np.arange(k.shape[-2])[None, :] <= np.arange(q.shape[-2])[:, None], scores, -np.inf)
    if attn_mask is not None:
        mask = _ops.wrap(attn_mask)._data
        if mask.dtype.kind == 'b': scores = np.where(mask, scores, -np.inf)
        elif mask.dtype == q.dtype: scores = scores + mask
        else: raise RuntimeError('SDPA mask must be boolean or match the query dtype')
    if scores.shape[-1]:
        maximum = scores.max(axis=-1, keepdims=True)
        exponentials = np.exp(scores - np.where(maximum == -np.inf, 0, maximum))
        denominator = exponentials.sum(axis=-1, keepdims=True)
        probabilities = np.divide(exponentials, denominator, out=np.zeros_like(exponentials), where=denominator != 0)
    else:
        probabilities = np.zeros_like(scores)

    # One shared raw-NumPy pullback avoids retaining score/probability graph
    # nodes and their logits allocation. Only probabilities and operands are
    # needed for backward, and the seed is never cached between traversals.
    operands, saved = [query, key, value], []
    mask_shape = None
    if isinstance(attn_mask, _tensor.Tensor):
        if attn_mask.dtype.kind == 'f':
            operands.append(attn_mask)
            mask_shape = attn_mask.shape
        else:
            saved.append(attn_mask)

    def backward(g, needs):
        logits_gradient = None
        if needs[0] or needs[1] or (mask_shape is not None and needs[3]):
            incoming = g @ np.swapaxes(v, -1, -2)
            logits_gradient = probabilities * (incoming - (incoming * probabilities).sum(axis=-1, keepdims=True))
            del incoming
        gradients = [
            _ops.unbroadcast((logits_gradient @ k) * factor, q.shape) if needs[0] else None,
            _ops.unbroadcast((np.swapaxes(logits_gradient, -1, -2) @ q) * factor, k.shape) if needs[1] else None,
            _ops.unbroadcast(np.swapaxes(probabilities, -1, -2) @ g, v.shape) if needs[2] else None,
        ]
        if mask_shape is not None:
            gradients.append(_ops.unbroadcast(logits_gradient, mask_shape) if needs[3] else None)
        return gradients

    return _autograd.joint_result(probabilities @ v, operands, backward, saved=saved)


def layer_norm_oracle(x, normalized_shape, weight=None, bias=None, eps=1e-5):
    """Separate analytical LayerNorm VJP for the library-oracle test path."""
    x = _ops.wrap(x)
    shape = tuple(normalized_shape)
    if not shape or tuple(x.shape[-len(shape):]) != shape: raise ValueError('normalized_shape does not match input')
    axes = tuple(range(x.ndim-len(shape), x.ndim))
    centered = x._data - x._data.mean(axis=axes, keepdims=True)
    inverse = 1 / np.sqrt(np.mean(centered ** 2, axis=axes, keepdims=True) + eps)
    normalized = centered * inverse
    scale = np.ones(shape, dtype=x.dtype) if weight is None else _ops.wrap(weight)._data
    value = normalized * scale
    if bias is not None: value = value + _ops.wrap(bias)._data
    def dx(g):
        scaled = g * scale
        return inverse * (scaled - scaled.mean(axis=axes, keepdims=True) - normalized * (scaled * normalized).mean(axis=axes, keepdims=True))
    edges = [(x, dx)]
    if weight is not None: edges.append((weight, lambda g: _ops.unbroadcast(g * normalized, weight.shape)))
    if bias is not None: edges.append((bias, lambda g: _ops.unbroadcast(g, bias.shape)))
    return _autograd.result(value, *edges)


def rms_norm_oracle(x, normalized_shape, weight=None, eps=None):
    """Independent raw NumPy RMS normalization with analytical input/scale VJPs."""
    shape = tuple(normalized_shape)
    if not shape or x.shape[-len(shape):] != shape: raise RuntimeError('Invalid RMSNorm shape')
    if x.dtype.kind != 'f': raise _errors.BrowserUnsupported('RMSNorm requires floating tensors')
    if weight is not None and (weight.shape != shape or weight.dtype != x.dtype):
        raise _errors.BrowserUnsupported('Mixed-dtype RMSNorm weights require the server')
    axes = tuple(range(x.ndim-len(shape), x.ndim))
    inverse = 1 / np.sqrt(np.mean(x._data ** 2, axis=axes, keepdims=True) + (np.finfo(x.dtype).eps if eps is None else eps))
    normalized = x._data * inverse
    scale = 1 if weight is None else weight._data
    def dx(g):
        scaled = g * scale
        return inverse * (scaled - normalized * (scaled * normalized).mean(axis=axes, keepdims=True))
    edges = [(x, dx)]
    if weight is not None: edges.append((weight, lambda g: _ops.unbroadcast(g * normalized, weight.shape)))
    return _autograd.result(normalized * scale, *edges)


def cosine_similarity(x1, x2, dim=1, eps=1e-8):
    """Native cosine normalization, including its distinct reverse/forward epsilon rules."""
    if not isinstance(x1, _tensor.Tensor) or not isinstance(x2, _tensor.Tensor):
        raise TypeError('cosine_similarity expects two tensors')
    if not isinstance(dim, (int, np.integer)) or isinstance(dim, (bool, np.bool_)):
        raise TypeError('cosine_similarity dim must be an integer')
    if not isinstance(eps, (int, float, np.integer, np.floating)):
        raise TypeError('cosine_similarity eps must be a number')
    if not eps >= 0: raise RuntimeError('cosine_similarity eps must be nonnegative')
    if any(x.dtype.kind == 'c' for x in (x1,x2)):
        raise RuntimeError('cosine_similarity requires a real floating result dtype')
    if any(x.dtype.kind == 'f' and x.dtype not in (np.dtype('float32'),np.dtype('float64')) for x in (x1,x2)):
        raise _errors.BrowserUnsupported('cosine_similarity supports real float32/float64')
    floating = [x.dtype for x in (x1,x2) if x.dtype.kind == 'f']
    if not floating: raise RuntimeError('cosine_similarity requires a floating result dtype')
