                  (a, lambda g: unbroadcast(np.einsum(f'{output},{right}->{left}', g, b_data), a_data.shape)),
                  (b, lambda g: unbroadcast(np.einsum(f'{output},{left}->{right}', g, a_data), b_data.shape)))


